<?php

// Declared inputs from the legacy card templates. Calculated material, measured
// corrosion and geometry summaries are intentionally supplied by their owners.
$field = function (string $label, string $section, string $legacy, string $type = 'text', ?array $options = null, ?array $groups = null, ?float $min = null, ?float $max = null): array {
    $rules = match ($type) {
        'number' => 'nullable|numeric',
        'integer' => 'nullable|integer',
        'date' => 'nullable|date_format:Y-m-d',
        default => 'nullable|string|max:2000',
    };
    if ($options !== null) {
        $rules .= '|in:'.implode(',', $options);
    }
    if ($min !== null) {
        $rules .= '|min:'.$min;
    }
    if ($max !== null) {
        $rules .= '|max:'.$max;
    }

    return array_filter(['label' => $label, 'section' => $section, 'legacy_keys' => [$legacy],
        'type' => in_array($type, ['number', 'integer'], true) ? 'number' : ($type === 'date' ? 'date' : null),
        'options' => $options, 'groups' => $groups, 'rules' => $rules], fn ($value) => $value !== null);
};
$yesNo = ['да', 'нет'];
$presence = ['присутствует', 'отсутствует'];
$temperature = fn ($label, $legacy) => $field($label, 'Рабочие параметры', $legacy, 'number', min: -273.15, max: 3000);
$pressure = fn ($label, $legacy) => $field($label, 'Рабочие параметры', $legacy, 'number', min: 0, max: 10000);

